let _particleTexture = null
let _toonGradientCache = null
let _sketchHatchTexture = null
export const _progressiveOrigMaterials = new Map()

export function getParticleTexture() {
    if (_particleTexture) return _particleTexture
    const size = 64
    const canvas = document.createElement("canvas")
    canvas.width = size
    canvas.height = size
    const ctx = canvas.getContext("2d", {
        willReadFrequently: true,
    })
    const gradient = ctx.createRadialGradient(
        size / 2,
        size / 2,
        0,
        size / 2,
        size / 2,
        size / 2
    )
    gradient.addColorStop(0, "rgba(255,255,255,1)")
    gradient.addColorStop(0.3, "rgba(255,255,255,0.8)")
    gradient.addColorStop(0.7, "rgba(255,255,255,0.3)")
    gradient.addColorStop(1, "rgba(255,255,255,0)")
    ctx.fillStyle = gradient
    ctx.fillRect(0, 0, size, size)
    _particleTexture = new THREE.CanvasTexture(canvas)
    return _particleTexture
}

export function createDissolveParticles(model, cfg) {
    const maxParticles = cfg.dissolveParticleMaxCount || 8000
    const initPositions = sampleModelPositions(model, maxParticles)
    const count = initPositions.length / 3

    const currentPos = new Float32Array(initPositions)
    const velocity = new Float32Array(count * 3)
    const maxOffset = new Float32Array(count)
    const dist = new Float32Array(count)
    const angle = new Float32Array(count)

    for (let i = 0; i < count; i++) {
        maxOffset[i] = Math.random() * 5.5 + 1.5
        velocity[i * 3] = Math.random() * 0.5 + 0.5
        velocity[i * 3 + 1] = Math.random() * 0.5 + 0.5
        velocity[i * 3 + 2] = Math.random() * 0.1
        dist[i] = 0.001
        angle[i] = Math.random() * Math.PI * 2
    }

    const geo = new THREE.BufferGeometry()
    geo.setAttribute(
        "position",
        new THREE.BufferAttribute(new Float32Array(initPositions), 3)
    )
    geo.setAttribute("aCurrentPos", new THREE.BufferAttribute(currentPos, 3))
    geo.setAttribute("aDist", new THREE.BufferAttribute(dist, 1))
    geo.setAttribute("aAngle", new THREE.BufferAttribute(angle, 1))

    const particleTex = getParticleTexture()

    const mat = new THREE.ShaderMaterial({
        transparent: true,
        blending: THREE.AdditiveBlending,
        depthWrite: false,
        uniforms: {
            uTexture: { value: particleTex },
            uPixelDensity: {
                value:
                    typeof window !== "undefined" ? window.devicePixelRatio : 1,
            },
            uProgress: { value: 0 },
            uEdge: { value: cfg.dissolveEdgeWidth || 0.8 },
            uAmp: { value: cfg.dissolveAmplitude || 16 },
            uFreq: { value: cfg.dissolveNoiseScale || 0.25 },
            uBaseSize: { value: cfg.dissolveParticleBaseSize || 80 },
            uColor: {
                value: parseColor(
                    cfg.dissolveParticleColor ||
                    cfg.dissolveEmissiveColor ||
                    "#4d9bff"
                ),
            },
        },
        vertexShader: `
${NOISE_GLSL}

uniform float uPixelDensity;
uniform float uBaseSize;
uniform float uFreq;
uniform float uAmp;
uniform float uEdge;
uniform float uProgress;

varying float vNoise;
varying float vAngle;

attribute vec3 aCurrentPos;
attribute float aDist;
attribute float aAngle;

void main() {
    vec3 pos = position;
    float noise = snoise(pos * uFreq) * uAmp;
    vNoise = noise;
    vAngle = aAngle;

    if (vNoise > uProgress - 2.0 && vNoise < uProgress + uEdge + 2.0) {
        pos = aCurrentPos;
    }

    vec4 modelPosition = modelMatrix * vec4(pos, 1.0);
    vec4 viewPosition = viewMatrix * modelPosition;
    vec4 projectedPosition = projectionMatrix * viewPosition;
    gl_Position = projectedPosition;

    float size = uBaseSize * uPixelDensity;
    size = size / (aDist + 1.0);
    gl_PointSize = size / -viewPosition.z;
}
`,
        fragmentShader: `
uniform vec3 uColor;
uniform float uEdge;
uniform float uProgress;
uniform sampler2D uTexture;

varying float vNoise;
varying float vAngle;

void main() {
    if (vNoise < uProgress) discard;
    if (vNoise > uProgress + uEdge) discard;

    vec2 coord = gl_PointCoord - 0.5;
    coord = coord * mat2(cos(vAngle), sin(vAngle), -sin(vAngle), cos(vAngle));
    coord = coord + 0.5;

    vec4 tex = texture2D(uTexture, coord);
    gl_FragColor = vec4(uColor * tex.rgb, tex.a);
}
`,
    })

    const points = new THREE.Points(geo, mat)
    points.frustumCulled = false

    return {
        points,
        geo,
        mat,
        state: {
            count,
            initPositions: new Float32Array(initPositions),
            currentPos,
            velocity,
            maxOffset,
            dist,
            angle,
            speed: cfg.dissolveParticleSpeed || 0.02,
            waveAmp: cfg.dissolveParticleWaveAmp || 0,
            velFactor: {
                x: cfg.dissolveParticleVelX || 2.5,
                y: cfg.dissolveParticleVelY || 2.0,
            },
        },
    }
}

export function updateDissolveParticles(pState) {
    const {
        count,
        initPositions,
        currentPos,
        velocity,
        maxOffset,
        dist,
        angle,
        speed,
        waveAmp,
        velFactor,
    } = pState

    for (let i = 0; i < count; i++) {
        const x = i * 3,
            y = i * 3 + 1,
            z = i * 3 + 2

        let vx = velocity[x] * velFactor.x
        let vy = velocity[y] * velFactor.y
        let vz = velocity[z]

        if (waveAmp > 0) {
            const px = currentPos[x],
                py = currentPos[y]
            vx += (Math.sin(py * 2) * 0.8 + Math.sin(py * 5) * 0.2) * waveAmp
            vy += (Math.sin(px * 2) * 0.6 + Math.sin(px * 1) * 0.9) * waveAmp
        }

        vx *= Math.abs(speed)
        vy *= Math.abs(speed)
        vz *= Math.abs(speed)

        currentPos[x] += vx
        currentPos[y] += vy
        currentPos[z] += vz

        const dx = currentPos[x] - initPositions[x]
        const dy = currentPos[y] - initPositions[y]
        const dz = currentPos[z] - initPositions[z]
        const dSq = dx * dx + dy * dy + dz * dz
        dist[i] = Math.sqrt(dSq)
        angle[i] += 0.01

        if (dSq > maxOffset[i] * maxOffset[i]) {
            currentPos[x] = initPositions[x]
            currentPos[y] = initPositions[y]
            currentPos[z] = initPositions[z]
        }
    }
}

export function syncParticleAttributes(pGeo, pState) {
    const cpAttr = pGeo.getAttribute("aCurrentPos")
    if (cpAttr) {
        cpAttr.array = pState.currentPos
        cpAttr.needsUpdate = true
    }
    const dAttr = pGeo.getAttribute("aDist")
    if (dAttr) {
        dAttr.array = pState.dist
        dAttr.needsUpdate = true
    }
    const aAttr = pGeo.getAttribute("aAngle")
    if (aAttr) {
        aAttr.array = pState.angle
        aAttr.needsUpdate = true
    }
}

export function disposeDissolveParticles(p) {
    if (!p) return
    p.geo?.dispose()
    p.mat?.dispose()
    if (p.points?.parent) p.points.parent.remove(p.points)
}

export function mapDissolveProgress(t, amp, edge) {
    const range = (amp || 16) + (edge || 0.8)
    return -range + t * 2 * range
}

export function getToonGradientMap(steps) {
    if (_toonGradientCache && _toonGradientCache._steps === steps)
        return _toonGradientCache
    const size = Math.max(steps, 2)
    const data = new Uint8Array(size)
    for (let i = 0; i < size; i++) {
        data[i] = Math.round((i / (size - 1)) * 255)
    }
    const tex = new THREE.DataTexture(data, size, 1, THREE.RedFormat)
    tex.minFilter = THREE.NearestFilter
    tex.magFilter = THREE.NearestFilter
    tex.needsUpdate = true
    tex._steps = steps
    _toonGradientCache = tex
    return tex
}

export function getSketchHatchTexture() {
    if (_sketchHatchTexture) return _sketchHatchTexture
    const size = 256
    const canvas = document.createElement("canvas")
    canvas.width = size
    canvas.height = size
    const ctx = canvas.getContext("2d", {
        willReadFrequently: false,
    })
    if (!ctx) return null
    ctx.fillStyle = "#f3f3ef"
    ctx.fillRect(0, 0, size, size)
    ctx.strokeStyle = "rgba(0,0,0,0.42)"
    ctx.lineWidth = 3
    for (let x = -size; x < size * 2; x += 12) {
        ctx.beginPath()
        ctx.moveTo(x, size)
        ctx.lineTo(x + size, 0)
        ctx.stroke()
    }
    const tex = new THREE.CanvasTexture(canvas)
    tex.wrapS = THREE.RepeatWrapping
    tex.wrapT = THREE.RepeatWrapping
    tex.repeat.set(2, 2)
    tex.colorSpace = THREE.SRGBColorSpace
    tex.needsUpdate = true
    _sketchHatchTexture = tex
    return tex
}

export function _isMeshOwnedByBone(mesh) {
    let p = mesh?.parent
    while (p) {
        if (p.isBone || p.type === "Bone") return true
        p = p.parent
    }
    return false
}

export function _cloneAsGlassPhysical(old) {
    if (old.isMeshPhysicalMaterial) return old.clone()

    const pm = new THREE.MeshPhysicalMaterial()
    const scalarKeys = [
        "color",
        "emissive",
        "metalness",
        "roughness",
        "opacity",
        "alphaTest",
        "side",
        "transmission",
        "thickness",
        "ior",
        "transparent",
        "depthWrite",
        "attenuationColor",
        "attenuationDistance",
        "envMapIntensity",
        "emissiveIntensity",
        "clearcoat",
        "clearcoatRoughness",
        "specularIntensity",
        "specularColor",
    ]
    for (const k of scalarKeys) {
        if (old[k] !== undefined)
            pm[k] = old[k]?.clone ? old[k].clone() : old[k]
    }
    const mapKeys = [
        "map",
        "normalMap",
        "aoMap",
        "emissiveMap",
        "alphaMap",
        "transmissionMap",
        "thicknessMap",
        "roughnessMap",
        "metalnessMap",
        "clearcoatMap",
        "clearcoatRoughnessMap",
        "clearcoatNormalMap",
        "envMap",
    ]
    for (const k of mapKeys) {
        if (old[k]) pm[k] = old[k]
    }
    if (old.normalScale) pm.normalScale = old.normalScale.clone()
    return pm
}

export function _stylizeGlassForToon(glassMat) {
    // Cleaner, more stylized glass: lower roughness, boost env reflections
    glassMat.roughness = Math.min(glassMat.roughness, 0.15)
    glassMat.metalness = Math.max(glassMat.metalness, 0.0)
    glassMat.envMapIntensity = Math.max(glassMat.envMapIntensity ?? 1, 0.8)
    // Ensure transmission pipeline is correct (no alpha blending conflict)
    if (glassMat.transmission > 0) {
        glassMat.transparent = false
        glassMat.depthWrite = true
        glassMat.opacity = 1
    }
    glassMat.needsUpdate = true
}

export function applyToonPreset(model, preset) {
    if (!model) return
    const gradMap = getToonGradientMap(preset.steps || 4)

    model.traverse((child) => {
        if (!_isMaterialPresetTarget(child)) return

        const mats = Array.isArray(child.material)
            ? child.material
            : [child.material]
        for (let i = 0; i < mats.length; i++) {
            const old = mats[i]

            // ── Glass: keep as MeshPhysicalMaterial with toon-style tweaks ──
            if (_isGlassMaterial(old)) {
                const glassMat = _cloneAsGlassPhysical(old)
                _stylizeGlassForToon(glassMat)
                if (Array.isArray(child.material)) child.material[i] = glassMat
                else child.material = glassMat
                continue
            }

            // ── Standard opaque: convert to MeshToonMaterial ──
            const toonMat = new THREE.MeshToonMaterial({
                color: old.color
                    ? old.color.clone()
                    : new THREE.Color(0xffffff),
                gradientMap: gradMap,
                side: old.side ?? THREE.FrontSide,
            })
            // Preserve texture maps from original material
            if (old.map) toonMat.map = old.map
            if (old.normalMap) {
                toonMat.normalMap = old.normalMap
                toonMat.normalScale =
                    old.normalScale?.clone() ?? new THREE.Vector2(1, 1)
            }
            if (old.aoMap) {
                toonMat.aoMap = old.aoMap
                toonMat.aoMapIntensity = old.aoMapIntensity ?? 1
            }
            if (old.emissive) toonMat.emissive = old.emissive.clone()
            if (old.emissiveMap) toonMat.emissiveMap = old.emissiveMap
            if (old.emissiveIntensity != null)
                toonMat.emissiveIntensity = old.emissiveIntensity
            if (old.alphaMap) toonMat.alphaMap = old.alphaMap
            if (old.transparent) toonMat.transparent = old.transparent
            if (old.opacity != null) toonMat.opacity = old.opacity
            if (old.alphaTest) toonMat.alphaTest = old.alphaTest

            toonMat.needsUpdate = true
            if (Array.isArray(child.material)) child.material[i] = toonMat
            else child.material = toonMat
        }
    })
}

export function applySketchPreset(model, preset) {
    if (!model) return
    const gradMap = getToonGradientMap(preset.steps || 3)
    const hatchMap = getSketchHatchTexture()
    const baseColor = parseColor(preset.color || "#f4f2ec")
    const outlineColor = parseColor(preset.outlineColor || "#050505")
    const thickness = preset.outlineThickness ?? 0.045
    const outlineMeshesToAdd = []

    removeOutlineMeshes(model)

    model.traverse((child) => {
        if (!_isMaterialPresetTarget(child)) return

        const mats = Array.isArray(child.material)
            ? child.material
            : [child.material]
        for (let i = 0; i < mats.length; i++) {
            const old = mats[i]

            if (_isGlassMaterial(old)) {
                const glassMat = _cloneAsGlassPhysical(old)
                glassMat.color = baseColor.clone()
                _stylizeGlassForToon(glassMat)
                if (Array.isArray(child.material)) child.material[i] = glassMat
                else child.material = glassMat
                continue
            }

            const sketchMat = new THREE.MeshToonMaterial({
                color: baseColor,
                gradientMap: gradMap,
                map: hatchMap,
                side: old.side ?? THREE.FrontSide,
            })
            if (old.normalMap) {
                sketchMat.normalMap = old.normalMap
                sketchMat.normalScale =
                    old.normalScale?.clone() ?? new THREE.Vector2(1, 1)
            }
            if (old.aoMap) {
                sketchMat.aoMap = old.aoMap
                sketchMat.aoMapIntensity = old.aoMapIntensity ?? 1
            }
            sketchMat.needsUpdate = true
            if (Array.isArray(child.material)) child.material[i] = sketchMat
            else child.material = sketchMat
        }

        const outlineMat = new THREE.MeshBasicMaterial({
            color: outlineColor,
            side: THREE.BackSide,
        })
        const outlineMesh = _createMaterialPresetOutlineMesh(
            child,
            outlineMat,
            thickness
        )
        if (outlineMesh) {
            outlineMeshesToAdd.push({
                parent: child.parent,
                mesh: outlineMesh,
            })
        } else {
            outlineMat.dispose()
        }
    })

    for (const entry of outlineMeshesToAdd) {
        if (entry.parent) entry.parent.add(entry.mesh)
    }
}

export function applyOutlinePreset(model, preset) {
    if (!model) return
    const baseColor = parseColor(preset.color || "#e8e0d8")
    const emissiveColor = parseColor(preset.emissiveColor || "#ffffff")
    const emissiveIntensity = preset.emissiveIntensity ?? 0
    const outlineColor = parseColor(preset.outlineColor || "#2a2a2a")
    const thickness = preset.outlineThickness ?? 0.06

    // First, remove any existing outline meshes from previous applications
    removeOutlineMeshes(model)

    // Apply flat/toon base material (glass preserved) + collect outline targets
    const outlineMeshesToAdd = []
    model.traverse((child) => {
        if (!_isMaterialPresetTarget(child)) return

        const mats = Array.isArray(child.material)
            ? child.material
            : [child.material]
        for (let i = 0; i < mats.length; i++) {
            const old = mats[i]

            if (_isGlassMaterial(old)) {
                // ── Glass: preserve physical material with stylized glass look ──
                const glassMat = _cloneAsGlassPhysical(old)
                _stylizeGlassForToon(glassMat)
                // Slightly more reflective for anime style
                glassMat.roughness = Math.min(glassMat.roughness, 0.1)
                if (Array.isArray(child.material)) child.material[i] = glassMat
                else child.material = glassMat
            } else {
                // ── Standard opaque: flat toon replacement ──
                const flatMat = new THREE.MeshToonMaterial({
                    color: baseColor,
                    emissive: emissiveColor,
                    emissiveIntensity,
                    gradientMap: getToonGradientMap(3),
                    side: THREE.FrontSide,
                })
                if (old.map) flatMat.map = old.map
                flatMat.needsUpdate = true
                if (Array.isArray(child.material)) child.material[i] = flatMat
                else child.material = flatMat
            }
        }

        // Create outline mesh (inverted hull) — always, including around glass meshes
        if (child.geometry) {
            const outlineMat = new THREE.MeshBasicMaterial({
                color: outlineColor,
                side: THREE.BackSide,
            })
            const outlineMesh = _createMaterialPresetOutlineMesh(
                child,
                outlineMat,
                thickness
            )
            if (outlineMesh) {
                outlineMeshesToAdd.push({
                    parent: child.parent,
                    mesh: outlineMesh,
                })
            } else {
                outlineMat.dispose()
            }
        }
    })

    // Add outline meshes after traversal to avoid modifying tree during traverse
    for (const entry of outlineMeshesToAdd) {
        if (entry.parent) entry.parent.add(entry.mesh)
    }
}

export function removeOutlineMeshes(model) {
    if (!model) return
    const toRemove = []
    model.traverse((child) => {
        if (child.__isOutlineMesh) toRemove.push(child)
    })
    for (const m of toRemove) {
        if (m.parent) m.parent.remove(m)
        if (m.__hasClonedGeometry) m.geometry?.dispose()
        m.geometry = null // don't dispose — shared with original
        m.material?.dispose()
    }
}

export function isSpecialPreset(presetKey) {
    const p = MATERIAL_PRESETS[presetKey]
    return p && p._type
}

export function _storeAndReplacePlaceholder(model) {
    _progressiveOrigMaterials.clear()
    const allTextures = []

    model.traverse((child) => {
        if (!child.isMesh) return

        const origMats = Array.isArray(child.material)
            ? child.material
            : [child.material]
        const textures = []

        // Collect all textures from original materials
        const texKeys = [
            "map",
            "normalMap",
            "roughnessMap",
            "metalnessMap",
            "aoMap",
            "emissiveMap",
            "bumpMap",
            "displacementMap",
            "alphaMap",
            "lightMap",
            "envMap",
            "clearcoatMap",
            "clearcoatNormalMap",
            "clearcoatRoughnessMap",
            "sheenColorMap",
            "sheenRoughnessMap",
            "transmissionMap",
            "thicknessMap",
            "iridescenceMap",
            "iridescenceThicknessMap",
            "specularIntensityMap",
            "specularColorMap",
        ]

        for (const mat of origMats) {
            for (const key of texKeys) {
                if (mat[key] && mat[key].isTexture) {
                    textures.push(mat[key])
                }
            }
        }

        _progressiveOrigMaterials.set(child.uuid, {
            original: Array.isArray(child.material)
                ? [...child.material]
                : child.material,
            textures,
        })
        allTextures.push(...textures)

        // Replace with placeholder
        const placeholder = _createPlaceholderMaterial()
        child.material = placeholder
    })

    // Deduplicate textures
    return [...new Set(allTextures)]
}

export async function _preloadTexturesProgressive(renderer, textures, onProgress) {
    if (!textures.length) {
        onProgress?.(1)
        return
    }

    let loaded = 0
    const total = textures.length

    for (const tex of textures) {
        try {
            // Force texture upload to GPU
            renderer.initTexture(tex)

            // If image not yet decoded, wait for it
            if (
                tex.image &&
                tex.image instanceof HTMLImageElement &&
                !tex.image.complete
            ) {
                await new Promise((resolve) => {
                    tex.image.onload = resolve
                    tex.image.onerror = resolve
                    // Fallback timeout
                    setTimeout(resolve, 5000)
                })
                renderer.initTexture(tex)
            }
        } catch (e) {
            // Silently continue — texture may already be uploaded
        }

        loaded++
        onProgress?.(loaded / total)
    }
}

export function clearFadeCache(model) {
    if (!model) return
    model.traverse((child) => {
        if (!child.isMesh) return
        if (child.__isOutlineMesh) return // Skip outline meshes
        const mats = Array.isArray(child.material)
            ? child.material
            : [child.material]
        mats.forEach((mat) => {
            if (!mat) return
            // Restore to full brightness before clearing cache
            if (mat._fadeOrigColor) {
                mat.color.copy(mat._fadeOrigColor)
            }
            if (mat._fadeOrigEmissive && mat.emissive) {
                mat.emissive.copy(mat._fadeOrigEmissive)
            }
            if (mat._fadeOrigEnvMapIntensity !== undefined) {
                mat.envMapIntensity = mat._fadeOrigEnvMapIntensity
            }
            // Now safe to delete cache
            delete mat._fadeOrigColor
            delete mat._fadeOrigEmissive
            delete mat._fadeOrigEnvMapIntensity
        })
    })
}

export function createDissolveMaterial(originalMaterial, dissolveConfig) {
    const {
        progress,
        noiseScale,
        edgeWidth,
        emissiveColor,
        emissiveIntensity,
        amplitude,
    } = dissolveConfig

    const mat = originalMaterial.clone()

    // Store dissolve properties (readable before shader compiles)
    mat.userData.dissolveProgress = progress
    mat.userData.noiseScale = noiseScale // frequency
    mat.userData.amplitude = amplitude ?? 16 // noise multiplier
    mat.userData.edgeWidth = edgeWidth
    mat.userData.emissiveColor = parseColor(emissiveColor)
    mat.userData.emissiveIntensity = emissiveIntensity

    mat.onBeforeCompile = (shader) => {
        shader.uniforms.uProgress = {
            value: mat.userData.dissolveProgress,
        }
        shader.uniforms.uFreq = { value: mat.userData.noiseScale }
        shader.uniforms.uAmp = { value: mat.userData.amplitude }
        shader.uniforms.uEdge = { value: mat.userData.edgeWidth }
        shader.uniforms.uEdgeColor = {
            value: mat.userData.emissiveColor,
        }
        shader.uniforms.uEdgeIntensity = {
            value: mat.userData.emissiveIntensity,
        }

        mat.userData.shaderUniforms = shader.uniforms

        // ── Vertex: pass object-space position to fragment ──
        shader.vertexShader = shader.vertexShader.replace(
            "#include <common>",
            `#include <common>
varying vec3 vPos;`
        )
        shader.vertexShader = shader.vertexShader.replace(
            "#include <begin_vertex>",
            `#include <begin_vertex>
vPos = position;`
        )

        // ── Fragment: inject noise, dissolve discard, edge glow ──
        shader.fragmentShader = shader.fragmentShader.replace(
            "#include <common>",
            `#include <common>
varying vec3 vPos;

uniform float uProgress;
uniform float uFreq;
uniform float uAmp;
uniform float uEdge;
uniform vec3 uEdgeColor;
uniform float uEdgeIntensity;

${NOISE_GLSL}
`
        )

        // Dissolve discard + edge coloring (after dithering, overwrite gl_FragColor)
        shader.fragmentShader = shader.fragmentShader.replace(
            "#include <dithering_fragment>",
            `#include <dithering_fragment>

    float noise = snoise(vPos * uFreq) * uAmp;
    if (noise < uProgress) discard;

    float edgeEnd = uProgress + uEdge;
    if (noise > uProgress && noise < edgeEnd) {
        float edgeMix = 1.0 - smoothstep(uProgress, edgeEnd, noise);
        vec3 glow = uEdgeColor * uEdgeIntensity * edgeMix;
        gl_FragColor = vec4(gl_FragColor.rgb + glow, gl_FragColor.a);
    }
`
        )
    }

    mat.needsUpdate = true
    return mat
}

export function sampleModelPositions(model, maxCount) {
    model.updateMatrixWorld(true) // Ensure matrices are current
    const positions = []
    model.traverse((child) => {
        if (!child.isMesh || child.__isOutlineMesh) return
        const posAttr = child.geometry?.getAttribute("position")
        if (!posAttr) return
        const worldMat = child.matrixWorld.clone()
        const modelInverse = model.matrixWorld.clone().invert()
        const localMat = modelInverse.multiply(worldMat)
        const v = new THREE.Vector3()
        for (let i = 0; i < posAttr.count; i++) {
            v.set(posAttr.getX(i), posAttr.getY(i), posAttr.getZ(i))
            v.applyMatrix4(localMat)
            positions.push(v.x, v.y, v.z)
        }
    })
    const totalVerts = positions.length / 3
    if (totalVerts <= maxCount) return new Float32Array(positions)
    const stride = Math.ceil(totalVerts / maxCount)
    const sampled = []
    for (let i = 0; i < totalVerts; i += stride) {
        sampled.push(
            positions[i * 3],
            positions[i * 3 + 1],
            positions[i * 3 + 2]
        )
    }
    return new Float32Array(sampled)
}

export function _startDissolveInForModel(st, cfg) {
    if (!st?.model) return false

    st.model.visible = true
    st.dissolveActive = true
    st.dissolveDirection = -1
    st.dissolveProgress = 1
    st._dissolvePendingIn = false

    st.model.traverse((child) => {
        if (!child.isMesh) return
        st.dissolveOriginalMaterials.set(child.uuid, child.material)
        const dissolveMat = createDissolveMaterial(child.material, {
            progress: mapDissolveProgress(
                1,
                cfg.dissolveAmplitude,
                cfg.dissolveEdgeWidth
            ),
            noiseScale: cfg.dissolveNoiseScale,
            amplitude: cfg.dissolveAmplitude,
            edgeWidth: cfg.dissolveEdgeWidth,
            emissiveColor: cfg.dissolveEmissiveColor,
            emissiveIntensity: cfg.dissolveEmissiveIntensity,
        })
        st.dissolveMaterials.set(child.uuid, dissolveMat)
        child.material = dissolveMat
    })

    if (cfg.dissolveParticlesEnabled) {
        disposeDissolveParticles(st.dissolveParticles)
        st.dissolveParticles = createDissolveParticles(st.model, cfg)
        st.dissolveParticles.points.position.copy(st.model.position)
        st.dissolveParticles.points.rotation.copy(st.model.rotation)
        st.dissolveParticles.points.scale.copy(st.model.scale)
        st.scene.add(st.dissolveParticles.points)
        st.dissolveParticles.mat.uniforms.uProgress.value = mapDissolveProgress(
            1,
            cfg.dissolveAmplitude,
            cfg.dissolveEdgeWidth
        )
    }

    return true
}

export function _isMaterialPresetTarget(child) {
    if (!child?.isMesh) return false
    if (child.__isOutlineMesh) return false
    if (child.visible === false) return false
    if (_isMeshOwnedByBone(child)) return false
    if (!child.geometry) return false
    const posAttr = child.geometry.getAttribute?.("position")
    return !posAttr || posAttr.count > 3
}

export function _createMaterialPresetOutlineMesh(child, outlineMat, thickness) {
    const outlineGeo = child.geometry.clone()
    if (!outlineGeo.attributes.normal) {
        outlineGeo.computeVertexNormals()
    }

    const posAttr = outlineGeo.attributes.position
    const normAttr = outlineGeo.attributes.normal

    if (posAttr && normAttr) {
        outlineGeo.computeBoundingSphere()
        const radius = outlineGeo.boundingSphere
            ? outlineGeo.boundingSphere.radius
            : 1
        const offset = thickness * radius

        for (let i = 0; i < posAttr.count; i++) {
            let x = posAttr.getX(i)
            let y = posAttr.getY(i)
            let z = posAttr.getZ(i)
            x += normAttr.getX(i) * offset
            y += normAttr.getY(i) * offset
            z += normAttr.getZ(i) * offset
            posAttr.setXYZ(i, x, y, z)
        }
        posAttr.needsUpdate = true
    }

    let outlineMesh
    if (child.isSkinnedMesh) {
        outlineMesh = new THREE.SkinnedMesh(outlineGeo, outlineMat)
        outlineMesh.bind(child.skeleton, child.bindMatrix)
    } else {
        outlineMesh = new THREE.Mesh(outlineGeo, outlineMat)
    }

    outlineMesh.__isOutlineMesh = true
    outlineMesh.__hasClonedGeometry = true
    outlineMesh.castShadow = false
    outlineMesh.receiveShadow = false
    outlineMesh.frustumCulled = child.frustumCulled
    outlineMesh.scale.copy(child.scale)
    outlineMesh.position.copy(child.position)
    outlineMesh.rotation.copy(child.rotation)
    outlineMesh.quaternion.copy(child.quaternion)

    if (child.morphTargetInfluences) {
        outlineMesh.morphTargetInfluences = child.morphTargetInfluences
        outlineMesh.morphTargetDictionary = child.morphTargetDictionary
    }

    return outlineMesh
}

export function _isGlassMaterial(mat) {
    return (mat.transmission && mat.transmission > 0) || !!mat.transmissionMap
}

export function loadImageAsSubScene(url, renderer, onLoaded, onError) {
    getSharedTextureLoader().load(
        url,
        (texture) => {
            texture.colorSpace = THREE.SRGBColorSpace
            texture.needsUpdate = true
            texture.anisotropy = _getOptimizedAnisotropy(renderer)

            const image = texture.image || {}
            const width = Math.max(1, image.width || 1)
            const height = Math.max(1, image.height || 1)
            const aspect = width / height
            const planeWidth = aspect >= 1 ? aspect : 1
            const planeHeight = aspect >= 1 ? 1 : 1 / aspect

            const geometry = new THREE.PlaneGeometry(planeWidth, planeHeight)
            const material = new THREE.MeshStandardMaterial({
                map: texture,
                transparent: true,
                alphaTest: 0.001,
                side: THREE.DoubleSide,
                roughness: 1,
                metalness: 0,
            })
            const mesh = new THREE.Mesh(geometry, material)
            mesh.name = "ImagePlane"
            mesh.castShadow = false
            mesh.receiveShadow = false

            const group = new THREE.Group()
            group.add(mesh)
            onLoaded(group, [])
        },
        undefined,
        onError
    )
}

export function _backupMaterial(mesh) {
    if (_origMaterialBackups.has(mesh.uuid)) return
    const mats = Array.isArray(mesh.material) ? mesh.material : [mesh.material]
    const clones = mats.map((m) => m.clone())
    _origMaterialBackups.set(mesh.uuid, clones)

    // FIX: Immediately assign the cloned materials to the mesh.
    // SkeletonUtils.clone() shares materials by default. This breaks the reference
    // so `applyMaterialOverride` only mutates THIS specific slot's material instance,
    // avoiding constant uniform uploads when slots share the same model.
    mesh.material = clones.length === 1 ? clones[0] : clones
}

export function _restoreMaterial(mesh) {
    const clones = _origMaterialBackups.get(mesh.uuid)
    if (!clones) return

    // Restore entire material objects (re-clone to avoid reference issues)
    const restored = clones.map((m) => m.clone())
    mesh.material = restored.length === 1 ? restored[0] : restored
}

export function _createPlaceholderMaterial() {
    return new THREE.MeshStandardMaterial({
        color: _progressivePlaceholderColor,
        metalness: 0.1,
        roughness: 0.7,
        envMapIntensity: 0.5,
    })
}

export function _restoreProgressiveMaterials(model) {
    model.traverse((child) => {
        if (!child.isMesh) return
        const stored = _progressiveOrigMaterials.get(child.uuid)
        if (!stored) return

        // Dispose placeholder
        const current = Array.isArray(child.material)
            ? child.material
            : [child.material]
        for (const m of current) {
            if (m !== stored.original && !Array.isArray(stored.original))
                m.dispose?.()
        }

        // Restore original
        child.material = stored.original
    })
    _progressiveOrigMaterials.clear()
}

export function setModelFade(model, factor) {
    if (!model) return
    model.traverse((child) => {
        if (!child.isMesh) return
        // Skip outline meshes — they use BackSide rendering;
        // darkening them separately would look wrong
        if (child.__isOutlineMesh) return
        const mats = Array.isArray(child.material)
            ? child.material
            : [child.material]
        mats.forEach((mat) => {
            if (!mat) return

            // Cache original values on first call per material
            if (mat._fadeOrigColor === undefined) {
                mat._fadeOrigColor = mat.color
                    ? mat.color.clone()
                    : new THREE.Color(1, 1, 1)
                mat._fadeOrigEmissive = mat.emissive
                    ? mat.emissive.clone()
                    : null
                mat._fadeOrigEnvMapIntensity = mat.envMapIntensity ?? 1
            }

            // Darken color & emissive by factor (0 = fully black, 1 = original)
            mat.color.copy(mat._fadeOrigColor).multiplyScalar(factor)
            if (mat._fadeOrigEmissive && mat.emissive) {
                mat.emissive.copy(mat._fadeOrigEmissive).multiplyScalar(factor)
            }
            mat.envMapIntensity = mat._fadeOrigEnvMapIntensity * factor

            // Cleanup cached originals when fully restored
            if (factor >= 1) {
                mat.color.copy(mat._fadeOrigColor)
                if (mat._fadeOrigEmissive && mat.emissive) {
                    mat.emissive.copy(mat._fadeOrigEmissive)
                }
                mat.envMapIntensity = mat._fadeOrigEnvMapIntensity
                delete mat._fadeOrigColor
                delete mat._fadeOrigEmissive
                delete mat._fadeOrigEnvMapIntensity
            }
        })
    })
}

export function applyMaterialOverride(model, cfg) {
    if (!model) return

    let preset =
        cfg.materialPreset !== "none"
            ? MATERIAL_PRESETS[cfg.materialPreset]
            : null

    if (preset && cfg.materialPreset === "animeLine") {
        preset = {
            ...preset,
            outlineThickness: cfg.animeLineThickness ?? 0.06,
            outlineColor: cfg.animeLineColor ?? "#050505",
            emissiveColor: cfg.animeLineEmissiveColor ?? "#ffffff",
            emissiveIntensity: cfg.animeLineEmissiveIntensity ?? 0.08,
        }
    } else if (preset && cfg.materialPreset === "sketchStyle") {
        preset = {
            ...preset,
            color: cfg.sketchBaseColor ?? "#f4f2ec",
            outlineThickness: cfg.sketchLineThickness ?? 0.045,
            outlineColor: cfg.sketchLineColor ?? "#050505",
            steps: cfg.sketchSteps ?? 3,
        }
    }

    // Backup original materials BEFORE any override (anime or PBR)
    const useOverride = cfg.overrideMaterial || preset
    if (useOverride) {
        model.traverse((child) => {
            if (child.isMesh) _backupMaterial(child)
        })
    }

    // ── Special presets (toon / outline) — handled separately ──
    if (preset && preset._type) {
        // Clean up outline meshes if switching away from outline
        if (preset._type !== "outline") removeOutlineMeshes(model)

        if (preset._type === "toon") {
            applyToonPreset(model, preset)
            return
        }
        if (preset._type === "sketch") {
            applySketchPreset(model, preset)
            return
        }
        if (preset._type === "outline") {
            applyOutlinePreset(model, preset)
            return
        }
    }

    // When switching FROM a special preset to normal/none, clean up outline meshes
    removeOutlineMeshes(model)
    if (!useOverride) {
        // Restore original materials when no override is active
        model.traverse((child) => {
            if (!child.isMesh) return
            _restoreMaterial(child)
        })
        return
    }

    model.traverse((child) => {
        if (!child.isMesh) return
        const mats = Array.isArray(child.material)
            ? child.material
            : [child.material]

        for (let i = 0; i < mats.length; i++) {
            let mat = mats[i]

            // Convert to MeshPhysicalMaterial — preserve ALL texture maps & properties
            if (!mat.isMeshPhysicalMaterial) {
                const oldMat = mat
                mat = new THREE.MeshPhysicalMaterial()

                // ── Copy ALL PBR texture maps ──
                const mapKeys = [
                    "map",
                    "normalMap",
                    "aoMap",
                    "roughnessMap",
                    "metalnessMap",
                    "emissiveMap",
                    "bumpMap",
                    "displacementMap",
                    "alphaMap",
                    "lightMap",
                    "envMap",
                    "clearcoatMap",
                    "clearcoatRoughnessMap",
                    "clearcoatNormalMap",
                    "transmissionMap",
                    "thicknessMap",
                    "sheenColorMap",
                    "sheenRoughnessMap",
                    "iridescenceMap",
                    "iridescenceThicknessMap",
                    "specularIntensityMap",
                    "specularColorMap",
                ]
                for (const k of mapKeys) {
                    if (oldMat[k]) mat[k] = oldMat[k]
                }

                // ── Copy ALL scalar/vector properties ──
                const scalarKeys = [
                    "color",
                    "emissive",
                    "metalness",
                    "roughness",
                    "opacity",
                    "alphaTest",
                    "transparent",
                    "side",
                    "flatShading",
                    "wireframe",
                    "vertexColors",
                    "normalScale",
                    "bumpScale",
                    "displacementScale",
                    "displacementBias",
                    "aoMapIntensity",
                    "lightMapIntensity",
                    "envMapIntensity",
                    "emissiveIntensity",
                    "reflectivity",
                    // Glass / Physical properties — preserve originals before override
                    "transmission",
                    "thickness",
                    "ior",
                    "clearcoat",
                    "clearcoatRoughness",
                    "iridescence",
                    "iridescenceIOR",
                    "sheen",
                    "sheenRoughness",
                    "sheenColor",
                    "specularIntensity",
                    "specularColor",
                    "attenuationColor",
                    "attenuationDistance",
                    "depthWrite",
                ]
                for (const k of scalarKeys) {
                    if (oldMat[k] !== undefined) {
                        mat[k] = oldMat[k]?.clone
                            ? oldMat[k].clone()
                            : oldMat[k]
                    }
                }

                if (Array.isArray(child.material)) child.material[i] = mat
                else child.material = mat
            }

            // ── Apply overrides ──
            // Three.js: final pixel value = textureMap × scalarValue
            // e.g. roughness=1.0 + roughnessMap → use map as-is
            // roughness=0.5 + roughnessMap → halve all map values
            const p = preset || {}
            const isManual = cfg.overrideMaterial

            mat.metalness = isManual
                ? cfg.metalness
                : (p.metalness ?? mat.metalness)
            mat.roughness = isManual
                ? cfg.roughness
                : (p.roughness ?? mat.roughness)
            mat.clearcoat = isManual
                ? cfg.clearcoat
                : (p.clearcoat ?? mat.clearcoat ?? 0)
            mat.clearcoatRoughness = isManual
                ? cfg.clearcoatRoughness
                : (p.clearcoatRoughness ?? mat.clearcoatRoughness ?? 0)

            const trans = isManual ? cfg.transmission : (p.transmission ?? 0)
            mat.transmission = trans
            mat.thickness = isManual ? cfg.thickness : (p.thickness ?? 0)
            mat.ior = isManual ? cfg.ior : (p.ior ?? 1.5)
            if (trans > 0) {
                // CRITICAL: transmission uses its own render pipeline (transmission buffer).
                // Setting transparent=true enables old-school alpha blending which CONFLICTS
                // with the transmission buffer → glass renders black/incorrect.
                // Three.js docs: "When using transmission, transparent should be false"
                mat.transparent = false
                mat.depthWrite = true
                mat.opacity = 1
            } else {
                // Non-transmissive: apply opacity override (alpha blending)
                const op = isManual
                    ? cfg.opacity
                    : (p.opacity ?? mat.opacity ?? 1)
                mat.opacity = op
                if (op < 1) {
                    mat.transparent = true
                    mat.depthWrite = false
                }
            }

            mat.iridescence = isManual ? cfg.iridescence : (p.iridescence ?? 0)
            mat.iridescenceIOR = isManual
                ? cfg.iridescenceIOR
                : (p.iridescenceIOR ?? 1.3)

            const sheenVal = isManual ? cfg.sheen : (p.sheen ?? 0)
            mat.sheen = sheenVal
            mat.sheenRoughness = isManual
                ? cfg.sheenRoughness
                : (p.sheenRoughness ?? 0.3)
            if (sheenVal > 0)
                mat.sheenColor = parseColor(
                    isManual ? cfg.sheenColor : (p.sheenColor ?? "#ffffff")
                )

            mat.envMapIntensity = isManual
                ? cfg.envMapIntensity
                : (p.envMapIntensity ?? 1)

            // Color: only override if preset has explicit color
            if (preset && p.color) mat.color = parseColor(p.color)

            const emInt = isManual
                ? cfg.emissiveIntensity
                : (p.emissiveIntensity ?? 0)
            mat.emissiveIntensity = emInt
            if (emInt > 0)
                mat.emissive = parseColor(
                    isManual
                        ? cfg.emissiveColor
                        : (p.emissiveColor ?? "#000000")
                )

            mat.reflectivity = isManual
                ? cfg.reflectivity
                : (p.reflectivity ?? 0.5)

            // Wireframe mode
            mat.wireframe = isManual
                ? (cfg.wireframe ?? false)
                : (p.wireframe ?? false)

            mat.needsUpdate = true
        }
    })
}
